SET NAMES utf8mb4;
CREATE TABLE admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(40) NOT NULL DEFAULT 'owner',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,phone VARCHAR(30) NOT NULL,whatsapp_phone VARCHAR(30),email VARCHAR(190),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(phone)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,slug VARCHAR(150) NOT NULL UNIQUE,sort_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,name VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,sku VARCHAR(80) NOT NULL UNIQUE,short_description VARCHAR(500),description TEXT,fragrance_family VARCHAR(100),concentration VARCHAR(80),gender VARCHAR(40),top_notes TEXT,heart_notes TEXT,base_notes TEXT,is_featured TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_variants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,variant_name VARCHAR(80) NOT NULL,volume_ml DECIMAL(8,2),sku VARCHAR(80) NOT NULL UNIQUE,price DECIMAL(12,2) NOT NULL,compare_at_price DECIMAL(12,2),stock_quantity INT UNSIGNED NOT NULL DEFAULT 0,is_active TINYINT(1) DEFAULT 1,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,image_path VARCHAR(500) NOT NULL,alt_text VARCHAR(255),sort_order INT DEFAULT 0,is_primary TINYINT(1) DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,content LONGTEXT,status ENUM('draft','published','archived') DEFAULT 'draft',seo_title VARCHAR(190),seo_description VARCHAR(320),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE navigation_menus(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,menu_location VARCHAR(50) DEFAULT 'header',label VARCHAR(120) NOT NULL,link_type VARCHAR(30) DEFAULT 'custom',link_value VARCHAR(500) NOT NULL,parent_id BIGINT UNSIGNED NULL,sort_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,FOREIGN KEY(parent_id) REFERENCES navigation_menus(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE homepage_sections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,section_key VARCHAR(80) NOT NULL UNIQUE,section_type VARCHAR(60) NOT NULL,title VARCHAR(180),subtitle VARCHAR(500),content_json JSON,sort_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE banners(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),image_desktop VARCHAR(500) NOT NULL,image_mobile VARCHAR(500),target_url VARCHAR(500),alt_text VARCHAR(255),sort_order INT DEFAULT 0,is_active TINYINT(1) DEFAULT 1,starts_at DATETIME NULL,ends_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE store_settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(40) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NULL,customer_name VARCHAR(160) NOT NULL,customer_phone VARCHAR(30) NOT NULL,customer_whatsapp VARCHAR(30),customer_email VARCHAR(190),delivery_address TEXT NOT NULL,city VARCHAR(100) NOT NULL,province VARCHAR(100) NOT NULL,postal_code VARCHAR(20),delivery_instructions TEXT,payment_method VARCHAR(40) DEFAULT 'cod',payment_status VARCHAR(30) DEFAULT 'unpaid',order_status VARCHAR(60) DEFAULT 'awaiting_whatsapp_confirmation',subtotal DECIMAL(12,2) NOT NULL,delivery_fee DECIMAL(12,2) DEFAULT 0,grand_total DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,INDEX(order_status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,variant_id BIGINT UNSIGNED NULL,product_name_snapshot VARCHAR(180) NOT NULL,variant_name_snapshot VARCHAR(80) NOT NULL,sku_snapshot VARCHAR(80) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,quantity INT UNSIGNED NOT NULL,line_total DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL,FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_status_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,old_status VARCHAR(60),new_status VARCHAR(60) NOT NULL,note VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO store_settings(setting_key,setting_value) VALUES('store_name','Ikki'),('currency','PKR'),('whatsapp_number','923094733789'),('default_delivery_fee','0') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
